def date_range(start: date, end: date, step: int = 1) -> Iterator[date]:
    if step <= 0 or not isinstance(step, int):
        raise ValueError('Step must be a positive integer')
    current = start
    while current <= end:
        yield current
        current += timedelta(days=step)

def list_(args: argparse.Namespace):
    if args.step:
        step = args.step
        if 'w' in step:
            step = int(step[:-1]) * DAYS_PER_WEEK
        else:
            step = int(step)
    else:
        step = 1
    for day in date_range(args.start, args.end, step):
        print(day.strftime(args.format))

